from pathlib import Path
from html import escape
DATA={"otaru":{"intro":"2026년 오타루 관광협회는 그해 크루즈 입항 예정 선박을 제3호 부두로 안내하지만 실제 선석·게이트는 항차별 재확인해야 합니다.","route":"제3호 부두 승객 출입구 확인 → 항만 보행 허용 구역을 따라 오타루 운하·운하플라자 관광 → 같은 게이트로 복귀. 화물 작업·행사에 따른 임시 이동 통제 여부 확인.","note":"2026년 9월 아스카Ⅲ는 제3부두 16·17번 선석 예시입니다. 다른 선박에 그 선석·하선시간을 그대로 적용하지 마세요.","links":[["오타루 관광협회 2026년 입항 계획","https://otaru.gr.jp/tourist/2026otarucruisekyakusenyotei2026"],["아스카Ⅲ 선석 사례","https://otaru.gr.jp/tourist/asukasa3-2026-9-26"]]},"takamatsu":{"intro":"다카마쓰의 리쓰린공원은 항만 시설이 아닌 시내 관광지입니다. 선박의 실제 접안 부두·승객 이동 지점을 먼저 확인하세요.","route":"실제 하선 게이트 → 지정 차량 탑승지점이나 유효한 대중교통 정류장 확인 → 리쓰린공원 방문 → 귀선편 탑승 장소와 출발시각 사전 확보 → 동일 게이트로 복귀.","note":"항차별 무료 셔틀, 리쓰린공원 방문 소요시간, 선사 귀선 마감은 공식 확정 정보가 확보되지 않았으므로 숫자를 임의 제공하지 않습니다.","links":[["가가와 공식 관광 안내","https://www.my-kagawa.jp/"],["고토덴 교통정보","https://www.kotoden.co.jp/"]]},"nagoya":{"intro":"나고야항관리조합은 가든부두 2·3호와 긴조부두 80·81호를 크루즈 접안 위치로 구분합니다. 두 장소는 전혀 다른 관광 출발점입니다.","route":"가든부두 접안이면 지정 출입구 확인 후 나고야항 수족관·항만 공원 권역을 우선 검토. 긴조부두 접안이면 아오나미선 긴조후토역 방향 보행 허용 동선과 수족관까지의 별도 교통을 확인하세요.","note":"관리조합 안내상 가든부두는 지하철 나고야코역 도보 약 5분, 긴조부두는 긴조후토역 도보 약 10분으로 안내되지만 승객 게이트에서 관광지까지의 보장 시간은 아닙니다. 가든부두 2호에는 일반인 출입 제한 안내가 있습니다.","links":[["나고야항관리조합 공식 크루즈 접안 장소","https://www.port-of-nagoya.jp/kanko/senpaku/cruiseguide/1004445.html"],["공식 2026년 입항 일정","https://www.port-of-nagoya.jp/kanko/senpaku/1002548/index.html"]]},"tokyo":{"intro":"도쿄 국제크루즈터미널역은 인근 철도역 사진입니다. 실제 도쿄 국제크루즈터미널 건물이나 선박 접안 부두를 촬영한 사진이 아닙니다.","route":"선사 발행 접안 터미널·승객 게이트 확인 → 항만 출입 허용 보행 동선으로 유리카모메 도쿄국제크루즈터미널역 또는 안내된 픽업존 확인 → 오다이바 한 권역만 관광 → 동일 게이트로 복귀.","note":"도쿄항 내 다른 접안지에서 출발하면 이 역으로의 동선은 적용되지 않습니다. 임시셔틀·귀선 마감시각은 항차별 별도 확인하세요.","links":[["도쿄 국제크루즈터미널 안내","https://www.tokyoport.or.jp/"],["유리카모메 철도 공식","https://www.yurikamome.co.jp/"]]},"sakaiminato":{"intro":"사카이미나토의 미즈키 시게루 로드는 도심 관광지이며 크루즈 출입 게이트와 동일한 위치가 아닙니다. 실제 승객 하선 위치를 확인하세요.","route":"실제 부두 및 보안 출입구 확인 → 공식 안내 셔틀·택시 또는 확인된 교통편으로 사카이미나토역·미즈키 시게루 로드 관광 → 귀선편 시간 확보 후 선박 게이트로 복귀.","note":"크루즈 선박별 부두와 무료 셔틀 유무가 달라질 수 있습니다. 이전 항차 후기의 운행표를 이번 항차에 적용하지 말고 선내·항만 운영 공지를 확인하세요.","links":[["돗토리현 관광청","https://www.tottori-guide.jp/"],["사카이미나토시 공식 정보","https://www.city.sakaiminato.lg.jp/"]]}}
for slug,d in DATA.items():
 p=Path('site/things-to-do')/(slug+'-cruise-port-day-trip')/'index.html'
 s=p.read_text()
 if 'id="v27-port-route"' in s: continue
 links=' · '.join(f'<a href="{escape(url)}" target="_blank" rel="noopener noreferrer">{escape(title)}</a>' for title,url in d['links'])
 section=f'''<section id="v27-port-route"><h2>실제 승객 게이트부터 관광지·귀선까지</h2><p><strong>항차별 확인:</strong> {escape(d['intro'])}</p><h3>관광 동선 예시</h3><p>{escape(d['route'])}</p><h3>귀선 안전·미확인 정보</h3><p>{escape(d['note'])}</p><p><strong>출항 시각과 최종 승객 귀선 마감은 다릅니다.</strong> 선사 앱·선내 공지에 나온 배정 부두·셔틀 승차장·귀선 게이트·최종 마감시간을 당일 재확인하고 복귀 여유를 두세요.</p><p class="small">공식 확인처: {links}. 검토일 2026-10-14. 개별 항차의 운영정보를 보장하는 자료는 아닙니다.</p></section>'''
 i=s.index('<section',s.index('<main'))
 p.write_text(s[:i]+section+s[i:])
 print('V27_ROUTE',slug)
